ST.xhtml:
parts.u1(
    number := 1,
    operator_ref := stat.operator,
    activity_ref := stat.activity,
    services_ref := parts.services);
parts.u2(
    number := 2,
    operator_ref := stat.operator,
    activity_ref := stat.activity,
    services_ref := parts.services);
parts.u3(
    number := 3,
    operator_ref := stat.operator,
    activity_ref := stat.activity,
    services_ref := parts.services);
parts.u4(
    number := 4,
    operator_ref := stat.operator,
    activity_ref := stat.activity,
    services_ref := parts.services);
parts.services( operator_ref := stat.operator );
stat.health := F_HealthStatus(
    superState := NOT(stat.init = InitializationStatus.shutdown),
    isGood := (NOT(stat.init = InitializationStatus.initializingFailed)) AND (((parts.u1.stat.health = HealthStatus.good) OR (parts.u1.stat.health = HealthStatus.warning)) AND (((parts.u2.stat.health = HealthStatus.good) OR (parts.u2.stat.health = HealthStatus.warning)) AND (((parts.u3.stat.health = HealthStatus.good) OR (parts.u3.stat.health = HealthStatus.warning)) AND (((parts.u4.stat.health = HealthStatus.good) OR (parts.u4.stat.health = HealthStatus.warning)) AND ((parts.services.stat.health = HealthStatus.good) OR (parts.services.stat.health = HealthStatus.warning)))))),
    hasWarning := (parts.u1.stat.health = HealthStatus.warning) OR ((parts.u2.stat.health = HealthStatus.warning) OR ((parts.u3.stat.health = HealthStatus.warning) OR ((parts.u4.stat.health = HealthStatus.warning) OR (parts.services.stat.health = HealthStatus.warning)))));
stat.busy := F_BusyStatus(
    superState := NOT(stat.init = InitializationStatus.shutdown),
    isBusy := (parts.u1.stat.busy = BusyStatus.busy) OR ((parts.u2.stat.busy = BusyStatus.busy) OR ((parts.u3.stat.busy = BusyStatus.busy) OR ((parts.u4.stat.busy = BusyStatus.busy) OR (parts.services.stat.busy = BusyStatus.busy)))));
stat.shuttersHealth := F_HealthStatus(
    superState := NOT(stat.init = InitializationStatus.shutdown),
    isGood := ((parts.u1.parts.dome.parts.shutter.stat.health = HealthStatus.good) OR (parts.u1.parts.dome.parts.shutter.stat.health = HealthStatus.warning)) AND (((parts.u2.parts.dome.parts.shutter.stat.health = HealthStatus.good) OR (parts.u2.parts.dome.parts.shutter.stat.health = HealthStatus.warning)) AND (((parts.u3.parts.dome.parts.shutter.stat.health = HealthStatus.good) OR (parts.u3.parts.dome.parts.shutter.stat.health = HealthStatus.warning)) AND ((parts.u4.parts.dome.parts.shutter.stat.health = HealthStatus.good) OR (parts.u4.parts.dome.parts.shutter.stat.health = HealthStatus.warning)))),
    hasWarning := (parts.u1.parts.dome.parts.shutter.stat.health = HealthStatus.warning) OR ((parts.u2.parts.dome.parts.shutter.stat.health = HealthStatus.warning) OR ((parts.u3.parts.dome.parts.shutter.stat.health = HealthStatus.warning) OR (parts.u4.parts.dome.parts.shutter.stat.health = HealthStatus.warning))));
stat.shuttersBusy := F_BusyStatus(
    superState := NOT(stat.init = InitializationStatus.shutdown),
    isBusy := (parts.u1.parts.dome.parts.shutter.stat.busy = BusyStatus.busy) OR ((parts.u2.parts.dome.parts.shutter.stat.busy = BusyStatus.busy) OR ((parts.u3.parts.dome.parts.shutter.stat.busy = BusyStatus.busy) OR (parts.u4.parts.dome.parts.shutter.stat.busy = BusyStatus.busy))));
stat.shuttersAperture := F_ApertureStatus(
    superState := NOT(stat.init = InitializationStatus.shutdown),
    isOpen := (parts.u1.parts.dome.parts.shutter.stat.aperture = ApertureStatus.open) OR ((parts.u2.parts.dome.parts.shutter.stat.aperture = ApertureStatus.open) OR ((parts.u3.parts.dome.parts.shutter.stat.aperture = ApertureStatus.open) OR ((parts.u4.parts.dome.parts.shutter.stat.aperture = ApertureStatus.open) OR ((parts.u1.parts.dome.parts.shutter.stat.aperture = ApertureStatus.partiallyOpen) OR ((parts.u2.parts.dome.parts.shutter.stat.aperture = ApertureStatus.partiallyOpen) OR ((parts.u3.parts.dome.parts.shutter.stat.aperture = ApertureStatus.partiallyOpen) OR (parts.u4.parts.dome.parts.shutter.stat.aperture = ApertureStatus.partiallyOpen))))))),
    isClosed := (parts.u1.parts.dome.parts.shutter.stat.aperture = ApertureStatus.closed) AND ((parts.u2.parts.dome.parts.shutter.stat.aperture = ApertureStatus.closed) AND ((parts.u3.parts.dome.parts.shutter.stat.aperture = ApertureStatus.closed) AND (parts.u4.parts.dome.parts.shutter.stat.aperture = ApertureStatus.closed))));
proc.initialize( isEnabled := NOT(stat.init = InitializationStatus.initializing) );
proc.lock( isEnabled := (stat.operator = OperatorStatus.tech) AND (stat.init = InitializationStatus.initialized) );
proc.unlock( isEnabled := (stat.operator = OperatorStatus.tech) AND (stat.init = InitializationStatus.locked) );
proc.changeOperator( isEnabled := TRUE );
proc.verifyPassword( isEnabled := TRUE );
proc.wakeUp( isEnabled := TRUE );
proc.goToSleep( isEnabled := TRUE );
proc.emergencyClose( isEnabled := NOT((parts.u1.parts.dome.parts.shutter.stat.aperture = ApertureStatus.closed) AND ((parts.u1.parts.dome.parts.shutter.stat.aperture = ApertureStatus.closed) AND ((parts.u1.parts.dome.parts.shutter.stat.aperture = ApertureStatus.closed) AND (parts.u1.parts.dome.parts.shutter.stat.aperture = ApertureStatus.closed)))) );
proc.point( isEnabled := parts.u1.proc.point.isEnabled OR (parts.u2.proc.point.isEnabled OR (parts.u3.proc.point.isEnabled OR parts.u4.proc.point.isEnabled)) );
proc.openDomes( isEnabled := parts.u1.parts.dome.parts.shutter.proc.open.isEnabled OR (parts.u2.parts.dome.parts.shutter.proc.open.isEnabled OR (parts.u3.parts.dome.parts.shutter.proc.open.isEnabled OR parts.u4.parts.dome.parts.shutter.proc.open.isEnabled)) );
proc.closeDomes( isEnabled := parts.u1.parts.dome.parts.shutter.proc.close.isEnabled OR (parts.u2.parts.dome.parts.shutter.proc.close.isEnabled OR (parts.u3.parts.dome.parts.shutter.proc.close.isEnabled OR parts.u4.parts.dome.parts.shutter.proc.close.isEnabled)) );
proc.stopDomes( isEnabled := parts.u1.parts.dome.parts.shutter.proc.stop.isEnabled OR (parts.u2.parts.dome.parts.shutter.proc.stop.isEnabled OR (parts.u3.parts.dome.parts.shutter.proc.stop.isEnabled OR parts.u4.parts.dome.parts.shutter.proc.stop.isEnabled)) );

IF do_request THEN
    do_request_result := request(
    alpha := set.alpha,
    delta := set.delta,
    u1 := set.u1,
    u2 := set.u2,
    u3 := set.u3,
    u4 := set.u4);
    do_request := FALSE;
END_IF;
SUPER^();

THIS^.get.alpha := alpha;
THIS^.get.delta := delta;
THIS^.get.u1 := u1;
THIS^.get.u2 := u2;
THIS^.get.u3 := u3;
THIS^.get.u4 := u4;
THIS^.stat.busy := BusyStatus.busy;
THIS^.stat.health := HealthStatus.good;

IF THIS^.stat.enabled = EnabledStatus.enabled THEN
    request := RequestResults.ACCEPTED;
    THIS^.start(
        alpha := alpha,
        delta := delta,
        u1 := u1,
        u2 := u2,
        u3 := u3,
        u4 := u4);
ELSE
    request := RequestResults.REJECTED;
END_IF;

IF do_request THEN
    do_request_result := request(
    u1 := set.u1,
    u2 := set.u2,
    u3 := set.u3,
    u4 := set.u4);
    do_request := FALSE;
END_IF;
SUPER^();

THIS^.get.u1 := u1;
THIS^.get.u2 := u2;
THIS^.get.u3 := u3;
THIS^.get.u4 := u4;
THIS^.stat.busy := BusyStatus.busy;
THIS^.stat.health := HealthStatus.good;

IF THIS^.stat.enabled = EnabledStatus.enabled THEN
    request := RequestResults.ACCEPTED;
    THIS^.start(
        u1 := u1,
        u2 := u2,
        u3 := u3,
        u4 := u4);
ELSE
    request := RequestResults.REJECTED;
END_IF;
